CREATE TABLE public.free_work_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id),section text NOT NULL CHECK(section IN('work-wanted','work-offered','service-providers','service-wanted')),category text NOT NULL,area text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,section,category,area));
GRANT SELECT ON public.free_work_entries TO authenticated; GRANT ALL ON public.free_work_entries TO service_role;
ALTER TABLE public.free_work_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_free_work_entries ON public.free_work_entries FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.free_work_pairs(member_id uuid NOT NULL REFERENCES public.profiles(id),owner_id uuid NOT NULL REFERENCES public.profiles(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(member_id,owner_id),CHECK(member_id<>owner_id));
GRANT SELECT ON public.free_work_pairs TO authenticated; GRANT ALL ON public.free_work_pairs TO service_role;
ALTER TABLE public.free_work_pairs ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_free_work_pairs ON public.free_work_pairs FOR SELECT TO authenticated USING(auth.uid() IN(member_id,owner_id));
CREATE TABLE public.free_work_interests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entry_id text NOT NULL,source text NOT NULL,user_id uuid NOT NULL REFERENCES public.profiles(id),section text NOT NULL,category text NOT NULL,area text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(entry_id,source,user_id));
GRANT SELECT ON public.free_work_interests TO authenticated; GRANT ALL ON public.free_work_interests TO service_role;
ALTER TABLE public.free_work_interests ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_free_work_interests ON public.free_work_interests FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.free_work_notice_queue(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id),entry_id text NOT NULL,source text NOT NULL,subscription_id uuid REFERENCES public.free_work_entries(id),notification_id uuid NOT NULL DEFAULT gen_random_uuid(),created_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz,UNIQUE(user_id,entry_id,source));
GRANT SELECT ON public.free_work_notice_queue TO authenticated; GRANT ALL ON public.free_work_notice_queue TO service_role;
ALTER TABLE public.free_work_notice_queue ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_free_work_notices ON public.free_work_notice_queue FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.free_work_category(v text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE lower(trim(v)) WHEN 'ప్లంబర్' THEN 'plumber' WHEN 'ఎలక్ట్రీషియన్' THEN 'electrician' WHEN 'ఎలక్ట్రిషియన్' THEN 'electrician' WHEN 'electrition' THEN 'electrician' WHEN 'షాప్ కీపర్' THEN 'shop keeper' WHEN 'సాఫ్ట్వేర్ ఇంజనీర్' THEN 'software engineer' WHEN 'డ్రైవర్' THEN 'driver' WHEN 'మేస్త్రీ' THEN 'mason' WHEN 'పెయింటర్' THEN 'painter' WHEN 'కార్పెంటర్' THEN 'carpenter' ELSE lower(trim(v)) END $$;
CREATE OR REPLACE FUNCTION public.free_work_opposite(v text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE v WHEN 'work-wanted' THEN 'work-offered' WHEN 'work-offered' THEN 'work-wanted' WHEN 'service-providers' THEN 'service-wanted' WHEN 'service-wanted' THEN 'service-providers' END $$;
CREATE OR REPLACE FUNCTION public.list_free_work(_section text,_area text DEFAULT '',_category text DEFAULT '') RETURNS TABLE(id text,source text,category text,area text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
SELECT e.id::text,'entry',e.category,e.area FROM public.free_work_entries e WHERE e.section=_section AND public.account_allowed(e.user_id) AND (_area='' OR lower(trim(e.area))=lower(trim(_area))) AND (_category='' OR public.free_work_category(e.category)=public.free_work_category(_category))
UNION ALL SELECT p.id::text,'post',coalesce(nullif(p.skill,''),p.category,p.title),coalesce(p.location,'') FROM public.posts p WHERE p.module='job' AND p.status='active' AND (p.visible_after IS NULL OR p.visible_after<=now()) AND (p.job_expires_at IS NULL OR p.job_expires_at>now()) AND public.account_allowed(p.user_id) AND _section=CASE WHEN p.service_type='service' THEN CASE WHEN p.kind='seeker' THEN 'service-providers' ELSE 'service-wanted' END ELSE CASE WHEN p.kind='seeker' THEN 'work-wanted' ELSE 'work-offered' END END AND (_area='' OR lower(trim(p.location))=lower(trim(_area)) OR p.area_scope='country') AND (_category='' OR public.free_work_category(coalesce(nullif(p.skill,''),p.category,p.title))=public.free_work_category(_category))
UNION ALL SELECT s.user_id::text,'provider',coalesce(nullif(s.category,''),s.service),s.town FROM public.service_profiles s WHERE _section='service-providers' AND s.published AND public.account_allowed(s.user_id) AND (_area='' OR lower(trim(s.town))=lower(trim(_area))) AND (_category='' OR public.free_work_category(coalesce(nullif(s.category,''),s.service))=public.free_work_category(_category)); $$;
GRANT EXECUTE ON FUNCTION public.list_free_work(text,text,text) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.list_free_work_interests(_section text,_area text DEFAULT '',_category text DEFAULT '') RETURNS TABLE(id text,source text,category text,area text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT i.id::text,'interest',i.category,i.area FROM public.free_work_interests i WHERE i.section=_section AND public.account_allowed(i.user_id) AND (_area='' OR lower(trim(i.area))=lower(trim(_area))) AND (_category='' OR public.free_work_category(i.category)=public.free_work_category(_category)); $$;
GRANT EXECUTE ON FUNCTION public.list_free_work_interests(text,text,text) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.queue_free_work_match() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sec text;cat text;place text;who uuid;eid text;src text;BEGIN
IF TG_TABLE_NAME='free_work_entries' THEN sec:=NEW.section;cat:=NEW.category;place:=NEW.area;who:=NEW.user_id;eid:=NEW.id::text;src:='entry';
ELSIF TG_TABLE_NAME='posts' THEN IF NEW.module<>'job' OR NEW.status<>'active' OR NEW.visible_after>now() OR NEW.job_expires_at<=now() THEN RETURN NEW;END IF;sec:=CASE WHEN NEW.service_type='service' THEN CASE WHEN NEW.kind='seeker' THEN 'service-providers' ELSE 'service-wanted' END ELSE CASE WHEN NEW.kind='seeker' THEN 'work-wanted' ELSE 'work-offered' END END;cat:=coalesce(nullif(NEW.skill,''),NEW.category,NEW.title);place:=NEW.location;who:=NEW.user_id;eid:=NEW.id::text;src:='post';
ELSE IF NOT NEW.published THEN RETURN NEW;END IF;sec:='service-providers';cat:=coalesce(nullif(NEW.category,''),NEW.service);place:=NEW.town;who:=NEW.user_id;eid:=NEW.user_id::text;src:='provider';END IF;
INSERT INTO public.free_work_notice_queue(user_id,entry_id,source,subscription_id) SELECT s.user_id,eid,src,s.id FROM public.free_work_entries s WHERE s.section=public.free_work_opposite(sec) AND s.user_id<>who AND s.created_at+interval '1 month'>now() AND public.free_work_category(s.category)=public.free_work_category(cat) AND lower(trim(s.area))=lower(trim(place)) AND public.account_allowed(who) AND public.account_allowed(s.user_id) ON CONFLICT DO NOTHING;RETURN NEW;END $$;
CREATE TRIGGER free_work_entry_matches AFTER INSERT ON public.free_work_entries FOR EACH ROW EXECUTE FUNCTION public.queue_free_work_match();
CREATE TRIGGER free_work_post_matches AFTER INSERT OR UPDATE ON public.posts FOR EACH ROW EXECUTE FUNCTION public.queue_free_work_match();
CREATE TRIGGER free_work_provider_matches AFTER INSERT OR UPDATE ON public.service_profiles FOR EACH ROW EXECUTE FUNCTION public.queue_free_work_match();
CREATE OR REPLACE FUNCTION public.join_free_work(_section text,_category text,_area text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE eid uuid;BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED';END IF;IF _section NOT IN('work-wanted','work-offered','service-providers','service-wanted') OR length(trim(_category)) NOT BETWEEN 2 AND 40 OR length(trim(_area)) NOT BETWEEN 1 AND 80 THEN RAISE EXCEPTION 'CATEGORY_AREA_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM public.discovery_categories WHERE section=_section AND public.free_work_category(name)=public.free_work_category(_category)) AND public.free_work_category(_category) NOT IN('plumber','electrician','shop keeper','software engineer','driver','mason','painter','carpenter') THEN RAISE EXCEPTION 'CATEGORY_REQUIRED';END IF;
INSERT INTO public.free_work_entries(user_id,section,category,area) VALUES(auth.uid(),_section,trim(_category),trim(_area)) ON CONFLICT(user_id,section,category,area) DO UPDATE SET category=EXCLUDED.category RETURNING id INTO eid;RETURN eid;END $$;
REVOKE ALL ON FUNCTION public.join_free_work(text,text,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.join_free_work(text,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.ring_free_work(_id text,_source text,_section text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target uuid;cat text;place text;BEGIN IF auth.uid() IS NULL OR NOT public.account_allowed(auth.uid()) THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED';END IF;
IF _source='interest' THEN SELECT user_id,category,area INTO target,cat,place FROM public.free_work_interests WHERE id::text=_id AND section=_section;
ELSE IF NOT EXISTS(SELECT 1 FROM public.list_free_work(_section) WHERE id=_id AND source=_source) THEN RAISE EXCEPTION 'ENTRY_UNAVAILABLE';END IF;
IF _source='entry' THEN SELECT user_id,category,area INTO target,cat,place FROM public.free_work_entries WHERE id::text=_id;ELSIF _source='post' THEN SELECT user_id,coalesce(nullif(skill,''),category,title),location INTO target,cat,place FROM public.posts WHERE id::text=_id;ELSIF _source='provider' THEN SELECT user_id,coalesce(nullif(category,''),service),town INTO target,cat,place FROM public.service_profiles WHERE user_id::text=_id AND published;END IF;END IF;
IF target IS NULL OR NOT public.account_allowed(target) THEN RAISE EXCEPTION 'ENTRY_UNAVAILABLE';END IF;IF target=auth.uid() THEN RETURN NULL;END IF;
INSERT INTO public.free_work_pairs(member_id,owner_id) VALUES(auth.uid(),target) ON CONFLICT DO NOTHING;
INSERT INTO public.free_work_interests(entry_id,source,user_id,section,category,area) VALUES(_id,_source,auth.uid(),_section,cat,place) ON CONFLICT DO NOTHING;
INSERT INTO public.free_work_notice_queue(user_id,entry_id,source) VALUES(target,_id||':'||auth.uid()::text,'bell') ON CONFLICT DO NOTHING;RETURN target;END $$;
REVOKE ALL ON FUNCTION public.ring_free_work(text,text,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.ring_free_work(text,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.free_work_chat(_other uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND auth.uid()<>_other AND public.account_allowed(auth.uid()) AND public.account_allowed(_other) AND EXISTS(SELECT 1 FROM public.free_work_pairs WHERE (member_id=auth.uid() AND owner_id=_other) OR (owner_id=auth.uid() AND member_id=_other)); $$;
ALTER FUNCTION public.can_post_chat(uuid,uuid) RENAME TO paid_post_chat;
CREATE FUNCTION public.can_post_chat(_post uuid DEFAULT NULL,_other uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.paid_post_chat(_post,_other) OR (_post IS NULL AND public.free_work_chat(_other)); $$;
GRANT EXECUTE ON FUNCTION public.can_post_chat(uuid,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.free_work_notice_allowed(_user uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.notification_preferences;z text;t timestamp;n integer;BEGIN IF NOT public.account_allowed(_user) THEN RETURN false;END IF;SELECT * INTO p FROM public.notification_preferences WHERE user_id=_user;z:=coalesce(p.timezone,'Asia/Kolkata');t:=now() AT TIME ZONE z;IF p.enabled=false OR NOT public.notice_window_open(now(),z) THEN RETURN false;END IF;IF p.quiet_start IS NOT NULL AND ((p.quiet_start<p.quiet_end AND t::time>=p.quiet_start AND t::time<p.quiet_end) OR (p.quiet_start>p.quiet_end AND (t::time>=p.quiet_start OR t::time<p.quiet_end))) THEN RETURN false;END IF;SELECT count(*) INTO n FROM public.notifications WHERE user_id=_user AND created_at>=date_trunc('day',t) AT TIME ZONE z;RETURN n<least(coalesce(p.daily_limit,5),5);END $$;
ALTER FUNCTION public.guard_prime99_notice() RENAME TO guard_paid_notice;
CREATE FUNCTION public.guard_prime99_notice() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.free_work_notice_queue WHERE notification_id=NEW.id AND user_id=NEW.user_id) THEN IF public.free_work_notice_allowed(NEW.user_id) THEN RETURN NEW;ELSE RETURN NULL;END IF;END IF;IF NOT public.has_paid_bell(NEW.user_id) OR EXISTS(SELECT 1 FROM public.notification_preferences WHERE user_id=NEW.user_id AND NOT enabled) THEN RETURN NULL;END IF;IF NOT public.can_notify(NEW.user_id) THEN RETURN NULL;END IF;RETURN NEW;END $$;
CREATE OR REPLACE FUNCTION public.dispatch_free_work_notices() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q record;n integer:=0;nid uuid;BEGIN FOR q IN SELECT * FROM public.free_work_notice_queue WHERE processed_at IS NULL ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT 100 LOOP
IF q.subscription_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.free_work_entries WHERE id=q.subscription_id AND created_at+interval '1 month'>now()) THEN UPDATE public.free_work_notice_queue SET processed_at=now() WHERE id=q.id;CONTINUE;END IF;
IF q.source<>'bell' AND NOT EXISTS(SELECT 1 FROM public.list_free_work((SELECT public.free_work_opposite(section) FROM public.free_work_entries WHERE id=q.subscription_id)) WHERE id=q.entry_id AND source=q.source) THEN CONTINUE;END IF;
PERFORM 1 FROM public.profiles WHERE id=q.user_id FOR UPDATE;IF NOT public.free_work_notice_allowed(q.user_id) THEN CONTINUE;END IF;nid:=NULL;
INSERT INTO public.notifications(id,user_id,message) VALUES(q.notification_id,q.user_id,CASE WHEN q.source='bell' THEN 'మీ పని గంటను ఒకరు నొక్కారు; చాట్‌లో స్పందించండి.' ELSE 'మీ ప్రాంతంలో మీ కేటగిరీకి సరిపోయే పని వచ్చింది; పని పెట్టెలో చూడండి.' END) RETURNING id INTO nid;
IF nid IS NOT NULL THEN UPDATE public.free_work_notice_queue SET processed_at=now() WHERE id=q.id;n:=n+1;END IF;END LOOP;RETURN n;END $$;
REVOKE ALL ON FUNCTION public.dispatch_free_work_notices() FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.dispatch_free_work_notices() TO service_role;
CREATE POLICY free_work_notifications_read ON public.notifications FOR SELECT TO authenticated USING(auth.uid()=user_id AND EXISTS(SELECT 1 FROM public.free_work_notice_queue q WHERE q.notification_id=notifications.id AND q.user_id=auth.uid()));
CREATE OR REPLACE FUNCTION public.notification_delivery_allowed(_user uuid,_notice uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.paid_alert_ready(_user) OR EXISTS(SELECT 1 FROM public.free_work_notice_queue WHERE user_id=_user AND notification_id=_notice); $$;
GRANT EXECUTE ON FUNCTION public.notification_delivery_allowed(uuid,uuid) TO authenticated,service_role;